        comp = []
        q = deque([(start_r, start_c)])
        visited.add((start_r, start_c))

        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and \
